Method.Implementation:
	#dim list As IHC.ITF.ITFCOMMON.HDD.Interface.LookupResponse
	#dim hddObj As IHC.ITF.ITFCOMMON.HDD.Interface.HddObject
	set hddObj = ""

	 try 
  {
	set list = pResponse.listOfHDDobj  
  	set listInd = list.Next("")
	while ( listInd '= "")
	{
		set hddObj = list.GetAt(listInd)
		if (hddObj.Index = index)
		{
			return hddObj
		}		
		set listInd = list.Next(listInd)
	}
	}  
 CATCH exceptionvar
 {
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)	     
         $$$LOGERROR("Exception in GetHddObject. Hdd response is empty. " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location)
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }
  }
	return ""
